def need(v,message):
    if not v:raise ValueError(message)
def sha_bytes(raw):return hashlib.sha256(raw).hexdigest()
def sha(path):
    h=hashlib.sha256()
    with Path(path).open('rb') as f:
        for b in iter(lambda:f.read(1<<20),b''):h.update(b)
    return h.hexdigest()
def read_json(path):return json.loads(Path(path).read_bytes())
def save(name,value):
    with (ROOT/name).open('xb') as f:f.write((json.dumps(value,sort_keys=True,indent=2)+'\n').encode())
def stamp(s):return (s.st_dev,s.st_ino,s.st_mode,s.st_nlink,s.st_size,s.st_mtime_ns,s.st_ctime_ns)
def source_identity(relative):
    path=SOURCE/relative
    fd=os.open(path,os.O_RDONLY|os.O_NOFOLLOW|os.O_NONBLOCK|os.O_CLOEXEC)
    try:
        before=os.fstat(fd)
        need(stat.S_ISREG(before.st_mode) and before.st_nlink==1,'non-regular input: '+relative)
        h=hashlib.sha256();g=hashlib.sha1(b'blob '+str(before.st_size).encode()+b'\0');count=0
        while True:
            b=os.read(fd,65536)
            if not b:break
            h.update(b);g.update(b);count+=len(b)
        need(count==before.st_size and stamp(before)==stamp(os.fstat(fd))==stamp(path.stat(follow_symlinks=False)),'input changed during hash: '+relative)
        return {'path':relative,'bytes':count,'sha256':h.hexdigest(),'git_blob_sha1':g.hexdigest()}
    finally:os.close(fd)
def equal_bytes(a,b):
    if Path(a).stat().st_size!=Path(b).stat().st_size:return False
    with Path(a).open('rb') as x,Path(b).open('rb') as y:
        while True:
            a=x.read(1<<20);b=y.read(1<<20)
            if a!=b:return False
            if not a:return True

